DROP STATISTICS IF EXISTS ess_mcv_correlated_ab;
DROP STATISTICS IF EXISTS ess_mcv_correlated_bc;
DROP STATISTICS IF EXISTS ess_mcv_correlated_cd;
CREATE STATISTICS ess_mcv_correlated_ab (mcv) ON a,b FROM ess_mcv_correlated;
ALTER STATISTICS ess_mcv_correlated_ab SET STATISTICS 10;
\echo WARMUP|correlated__ab__uniform10|1|1
ANALYZE ess_mcv_correlated;
SELECT 'META|' || 'correlated__ab__uniform10' || '|' || 1::text || '|' || e.stxname || '|' || e.oid::text || '|' || COALESCE(e.stxstattarget::text, 'NULL') || '|' || (d.stxdmcv IS NOT NULL)::text FROM pg_statistic_ext e LEFT JOIN pg_statistic_ext_data d ON d.stxoid = e.oid WHERE e.stxrelid = 'ess_mcv_correlated'::regclass AND e.stxname IN ('ess_mcv_correlated_ab', 'ess_mcv_correlated_bc', 'ess_mcv_correlated_cd') ORDER BY e.stxname;
